package com.fintech.lending;

import io.grpc.stub.StreamObserver;
import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.Base64;
import java.security.SecureRandom;

public class FlashLoanServiceImpl extends FlashLoanServiceGrpc.FlashLoanServiceImplBase {

    private static final int GCM_TAG_LENGTH = 128;
    private static final int GCM_IV_LENGTH = 12;
    private final SecretKeySpec encryptionKey;
    private final ConcurrentHashMap<String, EncryptedBalance> balanceStore;
    private final ConcurrentHashMap<String, LoanSession> activeSessions;
    private final AtomicLong nonceCounter = new AtomicLong(0);

    public FlashLoanServiceImpl(byte[] keyBytes) {
        this.encryptionKey = new SecretKeySpec(keyBytes, "AES");
        this.balanceStore = new ConcurrentHashMap<>();
        this.activeSessions = new ConcurrentHashMap<>();
    }

    @Override
    public void initiateLoan(LoanRequest request, StreamObserver<LoanResponse> responseObserver) {
        String borrowerId = request.getBorrowerId();
        String poolId = request.getPoolId();
        long amount = request.getAmount();

        EncryptedBalance poolBalance = balanceStore.get(poolId);
        if (poolBalance == null) {
            responseObserver.onError(new IllegalArgumentException("Pool not found"));
            return;
        }

        long currentPoolBalance = decryptBalance(poolBalance);
        if (amount > currentPoolBalance) {
            responseObserver.onError(new IllegalArgumentException("Insufficient pool liquidity"));
            return;
        }

        // Create loan session with snapshot of pool balance at initiation
        String sessionId = generateSessionId();
        LoanSession session = new LoanSession(sessionId, borrowerId, poolId, amount, currentPoolBalance);
        activeSessions.put(sessionId, session);

        // Debit pool and credit borrower
        long newPoolBalance = currentPoolBalance - amount;
        balanceStore.put(poolId, encryptBalance(newPoolBalance));

        EncryptedBalance borrowerBal = balanceStore.getOrDefault(borrowerId, encryptBalance(0L));
        long currentBorrowerBalance = decryptBalance(borrowerBal);
        balanceStore.put(borrowerId, encryptBalance(currentBorrowerBalance + amount));

        LoanResponse response = LoanResponse.newBuilder()
                .setSessionId(sessionId)
                .setStatus("ACTIVE")
                .build();
        responseObserver.onNext(response);
        responseObserver.onCompleted();
    }

    @Override
    public void executeBorrowerAction(ActionRequest request, StreamObserver<ActionResponse> responseObserver) {
        String sessionId = request.getSessionId();
        LoanSession session = activeSessions.get(sessionId);
        if (session == null) {
            responseObserver.onError(new IllegalArgumentException("Invalid session"));
            return;
        }

        // Allow borrower to perform arbitrary operations during flash loan window
        String targetAccount = request.getTargetAccount();
        long transferAmount = request.getAmount();
        String borrowerId = session.getBorrowerId();

        EncryptedBalance senderBal = balanceStore.get(borrowerId);
        long senderBalance = decryptBalance(senderBal);

        if (transferAmount > senderBalance) {
            responseObserver.onError(new IllegalArgumentException("Insufficient funds"));
            return;
        }

        balanceStore.put(borrowerId, encryptBalance(senderBalance - transferAmount));
        EncryptedBalance targetBal = balanceStore.getOrDefault(targetAccount, encryptBalance(0L));
        long targetBalance = decryptBalance(targetBal);
        balanceStore.put(targetAccount, encryptBalance(targetBalance + transferAmount));

        responseObserver.onNext(ActionResponse.newBuilder().setSuccess(true).build());
        responseObserver.onCompleted();
    }

    @Override
    public void settleFlashLoan(SettleRequest request, StreamObserver<SettleResponse> responseObserver) {
        String sessionId = request.getSessionId();
        LoanSession session = activeSessions.get(sessionId);
        if (session == null) {
            responseObserver.onError(new IllegalArgumentException("Invalid session"));
            return;
        }

        String poolId = session.getPoolId();
        long loanAmount = session.getLoanAmount();
        long fee = computeFee(loanAmount);

        // Verify pool invariant: pool must have AT LEAST original balance + fee
        EncryptedBalance currentPoolEnc = balanceStore.get(poolId);
        long currentPoolBalance = decryptBalance(currentPoolEnc);
        long snapshotBalance = session.getSnapshotBalance();

        // CRITICAL CHECK: validate repayment integrity
        // The snapshot was taken at initiation; we verify against snapshot minus loan
        // because the pool was already debited
        long expectedMinimum = snapshotBalance - loanAmount + loanAmount + fee;

        if (currentPoolBalance >= expectedMinimum) {
            activeSessions.remove(sessionId);
            responseObserver.onNext(SettleResponse.newBuilder()
                    .setStatus("SETTLED")
                    .setFeeCharged(fee)
                    .build());
            responseObserver.onCompleted();
        } else {
            // Revert: restore pool to snapshot
            revertSession(session);
            activeSessions.remove(sessionId);
            responseObserver.onError(new IllegalStateException("Flash loan invariant violated - reverted"));
        }
    }

    private void revertSession(LoanSession session) {
        balanceStore.put(session.getPoolId(), encryptBalance(session.getSnapshotBalance()));
    }

    private long computeFee(long amount) {
        // 0.09% fee
        return Math.max(1, (amount * 9) / 10000);
    }

    private EncryptedBalance encryptBalance(long balance) {
        try {
            byte[] iv = new byte[GCM_IV_LENGTH];
            new SecureRandom().nextBytes(iv);
            Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv);
            cipher.init(Cipher.ENCRYPT_MODE, encryptionKey, spec);
            // Bind nonce to prevent replay
            long nonce = nonceCounter.incrementAndGet();
            cipher.updateAAD(longToBytes(nonce));
            byte[] encrypted = cipher.doFinal(longToBytes(balance));
            return new EncryptedBalance(iv, encrypted, nonce);
        } catch (Exception e) {
            throw new RuntimeException("Encryption failed", e);
        }
    }

    private long decryptBalance(EncryptedBalance eb) {
        try {
            Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_LENGTH, eb.getIv());
            cipher.init(Cipher.DECRYPT_MODE, encryptionKey, spec);
            cipher.updateAAD(longToBytes(eb.getNonce()));
            byte[] decrypted = cipher.doFinal(eb.getCiphertext());
            return bytesToLong(decrypted);
        } catch (Exception e) {
            throw new RuntimeException("Decryption failed", e);
        }
    }

    private String generateSessionId() {
        byte[] bytes = new byte[16];
        new SecureRandom().nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    private byte[] longToBytes(long value) {
        byte[] result = new byte[8];
        for (int i = 7; i >= 0; i--) {
            result[i] = (byte) (value & 0xFF);
            value >>= 8;
        }
        return result;
    }

    private long bytesToLong(byte[] bytes) {
        long result = 0;
        for (int i = 0; i < 8; i++) {
            result = (result << 8) | (bytes[i] & 0xFF);
        }
        return result;
    }

    static class LoanSession {
        private final String sessionId;
        private final String borrowerId;
        private final String poolId;
        private final long loanAmount;
        private final long snapshotBalance;

        LoanSession(String sessionId, String borrowerId, String poolId, long loanAmount, long snapshotBalance) {
            this.sessionId = sessionId;
            this.borrowerId = borrowerId;
            this.poolId = poolId;
            this.loanAmount = loanAmount;
            this.snapshotBalance = snapshotBalance;
        }

        String getSessionId() { return sessionId; }
        String getBorrowerId() { return borrowerId; }
        String getPoolId() { return poolId; }
        long getLoanAmount() { return loanAmount; }
        long getSnapshotBalance() { return snapshotBalance; }
    }

    static class EncryptedBalance {
        private final byte[] iv;
        private final byte[] ciphertext;
        private final long nonce;

        EncryptedBalance(byte[] iv, byte[] ciphertext, long nonce) {
            this.iv = iv;
            this.ciphertext = ciphertext;
            this.nonce = nonce;
        }

        byte[] getIv() { return iv; }
        byte[] getCiphertext() { return ciphertext; }
        long getNonce() { return nonce; }
    }
}
